// In-memory NotificationProvider. Does not send real push notifications.
// Console logs are redacted (no user-facing text is generated by the mock itself).

import type { Result } from '@/core/result';

import type {
  NotificationProvider,
  PermissionStatus,
  PushNotificationPayload,
} from '../contracts/notification';
import type { HealthCheckResult } from '../types';
import { DEFAULT_MOCK_CONFIG, simulateMockIO, stableHash, type MockProviderConfig } from './config';

interface ScheduledNotification {
  readonly id: string;
  readonly payload: PushNotificationPayload;
  readonly triggerAt: number;
}

export interface MockNotificationProvider extends NotificationProvider {
  __scheduled(): readonly ScheduledNotification[];
}

export function createMockNotificationProvider(
  config: MockProviderConfig = DEFAULT_MOCK_CONFIG,
): MockNotificationProvider {
  let permission: PermissionStatus = 'granted';
  const scheduled = new Map<string, ScheduledNotification>();

  return Object.freeze({
    name: 'notification' as const,
    mode: 'mock' as const,
    capabilities: ['requestPermission', 'scheduleLocal', 'cancelScheduled'] as const,
    async healthCheck(): Promise<HealthCheckResult> {
      return { status: 'ok', checkedAt: Date.now() };
    },
    async requestPermission(): Promise<Result<PermissionStatus>> {
      const failure = await simulateMockIO(config);
      if (failure) return { ok: false, error: failure };
      permission = 'granted';
      return { ok: true, value: permission };
    },
    async scheduleLocal(
      payload: PushNotificationPayload,
      triggerSeconds: number,
    ): Promise<Result<string>> {
      const failure = await simulateMockIO(config);
      if (failure) return { ok: false, error: failure };
      const id = `mock-notif-${stableHash(JSON.stringify(payload) + Date.now())}`;
      scheduled.set(id, { id, payload, triggerAt: Date.now() + triggerSeconds * 1000 });
      return { ok: true, value: id };
    },
    async cancelScheduled(notificationId: string): Promise<Result<void>> {
      const failure = await simulateMockIO(config);
      if (failure) return { ok: false, error: failure };
      scheduled.delete(notificationId);
      return { ok: true, value: undefined };
    },
    __scheduled(): readonly ScheduledNotification[] {
      return Array.from(scheduled.values());
    },
  });
}
